#include <bits/stdc++.h>
#define inf 17446744073709551616ull
#define ull unsigned long long
using namespace std;

ull M, dp[18][250005];
ull fact[250005], inv_fact[250005];
ull N, K;

ull fast_pow(ull base, ull exp) {
    ull res = 1ULL;
    while (exp > 0) {
        if (exp & 1ULL) res = (res * base) % M;
        base = (base * base) % M;
        exp >>= 1ULL;
    }
    return res;
}

ull nCr(int a, int b) {
    return (((fact[a] * inv_fact[b]) % M) * inv_fact[a - b]) % M;
}

ull solve() {
    int i, j, l;
    fact[0] = 1ULL;
    for (i = 1; i <= N; i++) {
        fact[i] = (fact[i - 1] * (ull)i) % M;
    }
    inv_fact[N] = fast_pow(fact[N], M - 2ULL);
    for (i = N - 1; i >= 0; i--) {
        inv_fact[i] = (inv_fact[i + 1] * (ull)(i + 1)) % M;
    }
    for (i = 1; i <= N; i++) {
        dp[1][i] = inv_fact[i];
    }
    ull res = dp[1][N] * nCr(K, 1) % M;
    int t = min(17, (int)K);
    for (i = 2; i <= t; i++) {
        for (j = N; j; j = (j - 1) & N) {
            for (l = j; l; l = (l - 1) & j) {
                dp[i][j] += dp[i - 1][j ^ l] * inv_fact[l];
                if (dp[i][j] > inf) dp[i][j] %= M;
            }
            dp[i][j] %= M;
        }
        res += dp[i][N] * nCr(K, i);
        res %= M;
    }
    res *= fact[N];
    res %= M;
    return res;
}

int main() {
    cin >> N >> K >> M;
    ull answer = fast_pow(K, N);
    if (N & 1) {
        cout << answer << endl;
        return 0;
    }
    answer = (answer - solve() + M) % M;
    cout << answer << endl;
    return 0;
}
